def transmit_wire_C11() -> None:
    """COBOL logic"""
    global WS_WIRE_STATUS
    swiftsend_C11(WS_SWIFT_MESSAGE, WS_SWIFT_RESPONSE) # CALL 'SWIFTSEND' USING ws_swift_message ws_swift_response
    if SWIFT_STATUS == 'ACK':
        WS_WIRE_STATUS = 'SENT'
    else:
        WS_WIRE_STATUS = 'FAILED'
        reverse_debit_C11()

