    global WS_IC_IDX, WS_SEARCH_FROM, WS_SEARCH_TO, WS_IC_IDX2, WS_IC_COUNT, WS_IC_DIFF, IC_FROM_ENTITY, IC_TO_ENTITY, IC_AMOUNT
